// If a public mutation must remain for tooling, mirror syncUser's Greptile-hardened
// pattern: derive Clerk identity, refuse injected role, refuse conflicting emails.
export const createUserSelf = mutation({
  args: {},
  handler: async (ctx) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Unauthorized");
    const email = identity.email?.trim().toLowerCase();
    if (!email) throw new Error("User email not found in auth identity");
    let row = (await ctx.db.query("users").withIndex("by_email", (q) => q.eq("email", email)).collect())
      .find((r) => r.clerkId === identity.subject);
    if (row) return row._id;
    return await ctx.db.insert("users", { userId: identity.subject, email, clerkId: identity.subject, role: "student" });
  },
});

